
#[cfg(test)]
mod berserk55_disease56_render_development_tests {
    use super::*;
    #[test]
    fn disease_uses_original_multiply_pixel_policy_and_berserk_remains_screen() {
        let mut canvas=Canvas::new(1,1).unwrap();canvas.clear([248,128,64]);let frame=super::super::sprite::SpriteFrame{fragments:None,x_offset:0,y_offset:0,width:1,height:1,frame_type:0,unknown1:0,unknown2:0,rgba:vec![128,248,0,255]};let view=ViewProjection{anchor_cell:WorldCell{x:0,y:0},anchor_pixel:super::super::world_map::PixelPoint{x:0,y:0}};super::super::native_world_effects::Target::Canvas(&mut canvas).submit(&frame,WorldCell{x:0,y:0},view,reviewed_skill_mix(2230)).unwrap();assert_eq!(canvas.rgba(),&[132,132,0,255]);assert!(matches!(reviewed_skill_mix(3943),super::super::native_world_effects::Mix::Screen));
    }
    #[test]
    #[ignore="LITO_SHARED_RESOURCE_ROOT; original3943 eight banks/1361 and2230/839; memory fragments/history only"]
    fn original_berserk_heading_and_audio_survive_actor_departure_and_ring_rebuild() {
        let root:std::path::PathBuf=std::env::var_os("LITO_SHARED_RESOURCE_ROOT").expect("explicit shared root").into();let cancel=AtomicBool::new(false);let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();let b:Vec<_>=(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect();w.accept(&b).unwrap();}let own=w.own_actor().unwrap().clone();let id=0x71234567;let mut other=own.clone();other.id=id;other.incarnation+=1;other.heading=6;w.actors.insert(id,other);for gfx in [3943u16,2230]{let mut b=vec![0x37];b.extend(id.to_le_bytes());b.extend(gfx.to_le_bytes());w.accept(&b).unwrap();}let original=w.effects.clone();let view=ViewProjection{anchor_cell:WorldCell{x:i32::from(own.x),y:i32::from(own.y)},anchor_pixel:super::super::world_map::PixelPoint{x:400,y:300}};
        let mut e=Effects::default();e.prepare(&root,&w,&cancel);assert!(e.additional_error.is_none());assert_eq!(e.additional_bank.as_ref().unwrap().sources().filter(|s|s.name.starts_with("3943-")).count(),8);let mut fragments=vec![];let(receipt,audio)=e.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut fragments),view,0);assert!(receipt["load_error"].is_null());assert_eq!(audio.iter().filter(|a|a.sound==Some(839)&&a.actor==0&&a.prepared_audio.is_some()).count(),1);assert!(audio.iter().all(|a|a.sound!=Some(1361)));assert_eq!(receipt["effects"].as_array().unwrap().iter().find(|e|e["graphics"]==3943).unwrap()["heading"],6);drop(fragments);
        let h=e.history();w.actors.remove(&id);w.effects.clear();w.finite_effect_headings.clear();w.learned_skills.clear();let mut restored=Effects::default();restored.restore_history(h);restored.prepare(&root,&w,&cancel);let mut fragments=vec![];let(receipt,audio)=restored.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut fragments),view,125_000_000);assert_eq!(restored.started,2);assert_eq!(audio.iter().filter(|a|a.sound==Some(1361)&&a.actor==0&&a.prepared_audio.is_some()).count(),1);assert_eq!(receipt["effects"].as_array().unwrap().iter().find(|e|e["graphics"]==3943).unwrap()["sprite"],"3943-6.spr");drop(fragments);
        w.effects=original;let mut fragments=vec![];restored.draw_to(&w,&mut super::super::native_world_effects::Target::Fragments(&mut fragments),view,125_000_000);assert_eq!(restored.started,2);assert_eq!(restored.omitted,0);
    }
}
